sql.if:
AND (
UPPER(country_code) = UPPER(#{keyword})
OR country_name_zh = #{keyword}
OR country_name = #{keyword}
OR country_aliases = #{keyword}
OR CONCAT(',', IFNULL(country_aliases, ''), ',') LIKE CONCAT('%,', #{keyword}, ',%')
OR country_name_zh LIKE CONCAT('%', #{keyword}, '%')
OR country_name LIKE CONCAT('%', #{keyword}, '%')
)
